        "title": "দ্বিতীয় অধ্যায়: তীব্র টানাপোড়েন ও অন্তর্দাহ",
        "content": [
          "ঝড়ের তীব্রতা বাড়ছিল পাল্লা দিয়ে। জানালার কাঠের পাল্লাগুলো বাতাসে আছড়ে পড়ছিল, যেন কোনো অতৃপ্ত আত্মা ঘরের ভেতরে প্রবেশের জন্য মরিয়া হয়ে উঠেছে। হারিকেনের কাঁপা কাঁপা আলোয় তিনজনের ছায়া দেয়ালে দৈত্যের মতো কাঁপছিল।",
          "অচেনা দেয়ালে হেলান দিয়ে বসে ছিল, তার চোখের কোণ বেয়ে এক ফোঁটা তপ্ত অশ্রু গড়িয়ে পড়ল। সে ফ্যাসফেসে গলায় বলল, \"শফিক সাহেব, তুমি যার কথা বলছো, সে তো বহু বছর আগে এই পৃথিবী ছেড়ে চলে গেছে। আজ এত বছর পর সেই পুরনো ক্ষত আবার কেন নতুন করে রক্ত ঝরাবে?\"",
          "শফিক সাহেব একটি তাচ্ছিল্যের হাসি হেসে বলল, \"তুমি যাকে চলে যাওয়া ভাবছো, সে আসলে কখনো বিদায় নেয়নি। মানুষের পাপ আর অন্যায় কোনোদিন এমনি এমনি বাতাসে মিলিয়ে যায় না। তা ছায়ার মতো পিছু নেয়, যতক্ষণ না শেষ রক্তবিন্দু দিয়ে তার মূল্য শোধ করা হয়!\"",
          "কথাগুলো ঘরের প্রতিটি কোণে এক হিমশীতল আতঙ্কের সৃষ্টি করল। কামরুল শান্তভাবে জানালার কাছে গিয়ে দাঁড়াল। বৃষ্টির ছাঁট তার মুখে এসে লাগছিল, কিন্তু সে চোখের পলক ফেলল না। সে বুঝতে পারছিল, সামনে এক কঠিন পরীক্ষা। যে সত্যকে এতদিন সে হৃদয়ের গভীরতম অন্ধকারে চাপা দিয়ে রেখেছিল, আজ তা প্রকাশ্যে এসে দাঁড়িয়েছে। সে বলল, \"দোষ যদি আমার হয়ে থাকে, তবে তার শাস্তি আমি একা মাথা পেতে নেব। কিন্তু তোমাদের কাউকে আমি এই আগুনে পুড়তে দেব না।\"",
          "\"তুমি একা দায় নিতে চাইলেই কি সমাজ তোমাকে ছেড়ে দেবে?\" অচেনা উঠে দাঁড়িয়ে ক্ষোভে ফেটে পড়ল। \"আমরা একে অপরের পরিপূরক। সুখের দিনে যেমন আমরা পাশাপাশি হেসেছি, দুঃখের এই কালো রাতেও আমি তোমাকে একলা ফেলে কোথাও যাব না। মরতে হলে আমরা একসাথেই শেষ নিঃশ্বাস ফেলব!\"",
          "ভালোবাসা, আনুগত্য আর ত্যাগের এই তীব্র সংঘাত রাতের অন্ধকারকে যেন আরও মহিমান্বিত করে তুলল। বাইরে তখন অবিশ্রান্ত ধারায় বৃষ্টি ঝরে পড়ছে, আর ঘরের ভেতরে তিনটি মানবহৃদয় এক পরম সংকল্পের শক্তিতে পরস্পরকে জড়িয়ে ধরে শক্ত হয়ে দাঁড়াচ্ছিল।"
        ]
